<?php /* Contactos de recepción por WhatsApp (CU30): un botón por contacto con mensaje prellenado. */ ?>
<div class="page-heading"><div><span class="eyebrow">CONTACTO</span><h1>Contactar con recepción</h1><p>Realiza tus consultas administrativas por WhatsApp.</p></div></div>
